import Foundation

public func tokenOutputs(root: URL) throws -> [String: Data] {
    let source = try DesignSource(root: root)
    let catalog = "Packages/ChronoFlowKit/Sources/DesignSystem/Resources/Colors.xcassets"
    let info: [String: Any] = ["info": ["author": "xcode", "version": 1]]
    var outputs = ["\(catalog)/Contents.json": try jsonData(info)]
    var code = """
        // Generated by Tools/TokenGen. Do not edit.
        import Foundation

        nonisolated public enum TokenAppearance: String, CaseIterable, Sendable { case light, dark }
        nonisolated public struct TokenRGBA: Equatable, Sendable {
            public let red: Double
            public let green: Double
            public let blue: Double
            public let alpha: Double
        }
        nonisolated public struct SkyStop: Equatable, Sendable {
            public let location: Double
            public let color: TokenRGBA
        }
        nonisolated public enum ColorToken: String, CaseIterable, Sendable {
        """
    var report =
        "# TokenGen report\n\nSource: `_design/canvas/ds/chronoflow/tokens.json`. OKLCH → OKLab → linear Display P3 → clip → sRGB transfer curve. Conversion matrices follow [CSS Color 4](https://www.w3.org/TR/css-color-4/#color-conversion-code). Hex values are clipped sRGB.\n\n| Token | Light sRGB | Light P3 | Dark sRGB | Dark P3 |\n|---|---|---|---|---|\n"
    for name in DesignSource.names + DesignSource.authDerivedNames + DesignSource.wizardDerivedNames {
        code += "\ncase \(camelCase(name)) = \"\(camelCase(name))\""
    }
    code += "\npublic func components(for appearance: TokenAppearance) -> TokenRGBA {\nswitch (self, appearance) {\n"
    for name in DesignSource.names + DesignSource.authDerivedNames + DesignSource.wizardDerivedNames {
        var colors: [[String: Any]] = []
        var row = "| \(camelCase(name)) |"
        for appearance in ["light", "dark"] {
            let lab = try source.color(name, appearance)
            let rgb = lab.rgb(p3: true)
            let values = rgb.values.map(number)
            var entry: [String: Any] = [
                "idiom": "universal",
                "color": [
                    "color-space": "display-p3",
                    "components": [
                        "red": values[0], "green": values[1], "blue": values[2], "alpha": number(lab.alpha),
                    ],
                ],
            ]
            if appearance == "dark" { entry["appearances"] = [["appearance": "luminosity", "value": "dark"]] }
            colors.append(entry)
            code +=
                "case (.\(camelCase(name)), .\(appearance)): TokenRGBA(red: \(values[0]), green: \(values[1]), blue: \(values[2]), alpha: \(number(lab.alpha)))\n"
            row +=
                " \(lab.rgb(p3: false).hex)\(lab.alpha < 1 ? " α\(lab.alpha)" : "") | \(values.joined(separator: " ")) |"
        }
        let data = try jsonData(["info": info["info"]!, "colors": colors])
        outputs["\(catalog)/\(camelCase(name)).colorset/Contents.json"] = data
        if name == "sky-top" {
            outputs["App/Assets.xcassets/LaunchSky.colorset/Contents.json"] = data
            outputs["\(catalog)/LaunchSky.colorset/Contents.json"] = data
        }
        report += row + "\n"
    }
    code += "}}}\nnonisolated public enum SkyRamp {\n"
    for appearance in ["light", "dark"] {
        let stops = try source.ramp(appearance)
        code += "public static var \(appearance): [SkyStop] { [\n"
        for stop in stops {
            let v = stop.color.values.map(number)
            code +=
                "SkyStop(location: \(number(stop.location)), color: TokenRGBA(red: \(v[0]), green: \(v[1]), blue: \(v[2]), alpha: 1)),\n"
        }
        code += "] }\n"
        report +=
            "\n\(appearance.capitalized) sky: \(stops.count) stops, including exact mid \(try source.midStop(appearance)); encoded Display P3 channel interpolation checked at 1001 points to ±1/255.\n"
    }
    let scale = try captures(#"scale\(([\d.]+)\)"#, in: source.theme)[0]
    let opacity = try captures(#"opacity: ([\d.]+); \}"#, in: source.theme)[0]
    let duration = try captures(#"transition: transform ([\d.]+)ms ease"#, in: source.theme)[0]
    guard scale == "0.97", opacity == "0.85", duration == "120",
        source.theme.contains(".cf-press { transition: none; }"),
        source.theme.contains(".cf-press:active { transform: none; }")
    else {
        throw GenerationError.invalid("cf-press differs from plan")
    }
    code +=
        "}\nnonisolated public enum PressTokens { public static var scale: Double { \(scale) }; public static var opacity: Double { \(opacity) }; public static var duration: Double { \(duration) / 1000 }; public static var curve: [Double] { [0.25, 0.1, 0.25, 1] } }\n"
    let splashBoard = try String(
        contentsOf: root.appending(path: "_design/canvas/SplashScreen.dc.html"), encoding: .utf8)
    guard splashBoard.contains("background: #fff;"),
        splashBoard.contains("box-shadow: 0 0 80px 20px"),
        splashBoard.contains("box-shadow: 0 0 10px 2px rgba(255,255,255,0.8)")
    else {
        throw GenerationError.invalid("splash plane white differs from plan")
    }
    let halo =
        [(0.0, 0.0), (90.0 / 250, 0.0)]
        + stride(from: 90.01, through: 250, by: 2).map {
            ($0 / 250, blurredDisc(radius: $0, disc: 110, sigma: 40) * 0.45)
        } + [(1.0, 0.0)]
    let plane = stride(from: 0.0, through: 24, by: 0.5).map {
        blurredDisc(radius: $0, disc: 6, sigma: 5) * 0.8
    }
    code +=
        "nonisolated public enum LaunchPaint {\npublic static var white: TokenRGBA { TokenRGBA(red: 1, green: 1, blue: 1, alpha: 1) }\n"
    code +=
        "public static var haloStops: [(Double, Double)] { ["
        + halo.map { "(\(number($0.0)), \(number($0.1)))" }.joined(separator: ",") + "] }\n"
    code += "public static var planeAlphas: [Double] { [" + plane.map(number).joined(separator: ",") + "] }\n}\n"
    outputs["Packages/ChronoFlowKit/Sources/DesignSystem/CfSky.generated.swift"] = try formattedSwift(code, root: root)
    outputs["Tools/TokenGen/TokenGenReport.md"] = Data(report.utf8)
    outputs["Packages/ChronoFlowKit/Sources/DesignSystem/WelcomeTokens.generated.swift"] = try welcomeTokens(root: root)
    outputs["Packages/ChronoFlowKit/Sources/DesignSystem/PlanUITokens.generated.swift"] = try planUITokens(root: root)
    outputs["Packages/ChronoFlowKit/Sources/DesignSystem/AuthTokens.generated.swift"] = try authTokens(root: root)
    outputs["Packages/ChronoFlowKit/Sources/DesignSystem/SettingsTokens.generated.swift"] = try settingsTokens(
        root: root)
    outputs["Packages/ChronoFlowKit/Sources/DesignSystem/TermsTokens.generated.swift"] = try termsTokens(root: root)
    outputs.merge(try planTokenOutputs(root: root)) { _, new in new }
    return outputs
}

private func blurredDisc(radius: Double, disc: Double, sigma: Double) -> Double {
    let step = disc / 256
    return (0..<256).reduce(0) { result, index in
        let y = (Double(index) + 0.5) * step
        let edge = sqrt(disc * disc - y * y)
        let horizontal =
            (erf((edge - radius) / (sqrt(2) * sigma))
                - erf((-edge - radius) / (sqrt(2) * sigma))) / 2
        return result + horizontal * exp(-y * y / (2 * sigma * sigma))
            / (sqrt(2 * .pi) * sigma) * step * 2
    }
}
